const text = String($json.nachricht ?? "");

const match = text.match(/\bTEST-\d{4}\b/i);

return {
  json: {
    ...$json,
    bestellnummer: match ? match[0].toUpperCase() : null
  }
};

const messageItem = $('Bestellnummer erkennen').first(0, $runIndex);

if (!messageItem) {
  throw new Error('Kundenanfrage nicht gefunden');
}

const message = messageItem.json;
const order = $json;

const normalize = (value) =>
  String(value ?? '').trim().toLowerCase();

let pruefstatus = 'berechtigt';

if (!message.bestellnummer) {
  pruefstatus = 'bestellnummer_fehlt';
} else if (order.abfrage_status === 'timeout') {
  pruefstatus = 'technischer_fehler';
} else if (!order.bestellnummer) {
  pruefstatus = 'bestellung_nicht_gefunden';
} else if (order.bestellnummer !== message.bestellnummer) {
  pruefstatus = 'datenfehler';
} else if (
  !order.kundenadresse ||
  normalize(message.absender) !== normalize(order.kundenadresse)
) {
  pruefstatus = 'nicht_berechtigt';
}

const autorisiert = pruefstatus === 'berechtigt';

return {
  json: {
    eingangs_id: message.eingangs_id,
    nachrichten_id: message.nachrichten_id,
    absender: message.absender,
    nachricht: message.nachricht,
    bestellnummer: message.bestellnummer,
    pruefstatus,
    autorisiert,
    kanal: autorisiert ? order.kanal : null,
    datenstand: autorisiert ? order.datenstand : null,
    datenquelle: !message.bestellnummer
      ? 'keine Bestellnummer angegeben'
      : order.bestellnummer
        ? 'test_bestellungen'
        : 'keine Bestellung gefunden',
    pruefung_noetig: true
  }
};

const originalText = String($json.nachricht ?? "");

// Customer text is data, never a system instruction.
const manipulationsverdacht =
  /systemanweisung\s*:|ignoriere alle bisherigen regeln|gib alle kundendaten aus/i
    .test(originalText);

// Ignore the instruction section when identifying the request.
const text = originalText
  .split(/systemanweisung\s*:/i)[0]
  .toLowerCase();

let anliegen = "sonstige_anfrage";

if (/stornier|erstattung|rückerstattung/.test(text)) {
  anliegen = "storno_erstattung";
} else if (
  /zugestellt/.test(text) &&
  /nicht angekommen|nichts angekommen|nicht erhalten/.test(text)
) {
  anliegen = "zustellung_bestritten";
} else if (/schläuch|schlauch|teillieferung|kommt alles zusammen/.test(text)) {
  anliegen = "teillieferung";
} else if (/sendungsnummer|trackingnummer|bestelldaten/.test(text)) {
  anliegen = "bestelldaten_anfragen";
} else if (
  /wo bleibt|wo ist|status|versendet|versand|liefertermin/.test(text)
) {
  anliegen = "versandstatus";
}

return {
  json: {
    ...$json,
    anliegen,
    manipulationsverdacht
  }
};

const d = $json;
const order = String(d.datenstand ?? "");
const nr = d.bestellnummer || "ohne Bestellnummer";

const tracking = order.match(/Tracking:\s*(TEST-(?:DHL|GLS)-\d+)/i)?.[1] ?? null;

let antwortentwurf = "";
let interne_aufgabe = "";
let naechster_schritt = "";

// First handle missing data, errors and access restrictions.
if (d.pruefstatus === "bestellnummer_fehlt") {
  antwortentwurf = "Vielen Dank für Ihre Nachricht. Bitte teilen Sie uns Ihre Bestellnummer mit, damit wir Ihre Anfrage prüfen können.";
  interne_aufgabe = "Anfrage ohne Bestellnummer prüfen.";
  naechster_schritt = "Bestellnummer beim Kunden anfragen.";

} else if (d.pruefstatus === "technischer_fehler") {
  antwortentwurf = "Vielen Dank für Ihre Nachricht. Wir können den Bestellstatus aktuell wegen eines technischen Problems nicht prüfen. Unser Kundenservice wird die Anfrage bearbeiten.";
  interne_aufgabe = `Technischen Fehler bei ${nr} prüfen. Bestellstatus nicht verfügbar.`;
  naechster_schritt = "Technischen Fehler prüfen, danach Bestellung erneut abfragen.";

} else if (d.pruefstatus === "bestellung_nicht_gefunden") {
  antwortentwurf = "Vielen Dank für Ihre Nachricht. Wir konnten die angegebene Bestellnummer nicht finden. Bitte prüfen Sie die Nummer.";
  interne_aufgabe = `Bestellnummer ${nr} konnte nicht gefunden werden. Anfrage prüfen.`;
  naechster_schritt = "Bestellnummer prüfen lassen.";

} else if (d.pruefstatus === "nicht_berechtigt") {
  antwortentwurf = "Vielen Dank für Ihre Anfrage. Bevor wir Bestelldaten mitteilen können, muss unser Kundenservice Ihre Anfrage prüfen.";
  interne_aufgabe = `Absender und Bestellung ${nr} stimmen nicht überein. Identität prüfen.`;
  naechster_schritt = "Absender prüfen. Keine Bestelldaten herausgeben.";

} else if (d.pruefstatus !== "berechtigt" || !order) {
  antwortentwurf = "Vielen Dank für Ihre Anfrage. Unser Kundenservice prüft Ihr Anliegen und meldet sich bei Ihnen.";
  interne_aufgabe = `Unklare oder fehlende Daten für ${nr} prüfen.`;
  naechster_schritt = "Daten manuell prüfen.";

} else {

  // Only authorised requests reach these templates.
  switch (d.anliegen) {

    case "versandstatus":
      if (/Versandstatus:\s*unterwegs/i.test(order)) {
        antwortentwurf = `Ihre Bestellung ${nr} wurde versendet und ist laut unseren Daten unterwegs.${tracking ? ` Die Sendungsnummer lautet ${tracking}.` : ""} Ein bestätigter Liefertermin liegt uns nicht vor.`;
      } else if (/noch kein Versand hinterlegt/i.test(order)) {
        antwortentwurf = `Für Ihre Bestellung ${nr} ist noch kein Versand hinterlegt. Einen Liefertermin können wir aktuell nicht bestätigen.`;
      } else {
        antwortentwurf = "Vielen Dank für Ihre Anfrage. Wir prüfen den Versandstatus Ihrer Bestellung.";
        interne_aufgabe = `Versandstatus für ${nr} prüfen.`;
      }
      naechster_schritt = "Antwortentwurf prüfen und freigeben.";
      break;

    case "teillieferung":
      if (/Nur der Filter ist versendet/i.test(order) &&
          /Schläuche ist kein Versand hinterlegt/i.test(order)) {
        antwortentwurf = `Bei Ihrer Bestellung ${nr} wurde der Filter versendet.${tracking ? ` Die Sendungsnummer lautet ${tracking}.` : ""} Für die zwei Schläuche ist noch kein Versand hinterlegt. Ob alle Artikel zusammen ankommen, können wir nicht bestätigen.`;
      } else {
        antwortentwurf = "Vielen Dank für Ihre Anfrage. Wir prüfen die einzelnen Artikel Ihrer Bestellung.";
      }
      interne_aufgabe = `Offene Artikel und Teillieferung für ${nr} prüfen.`;
      naechster_schritt = "Versand der restlichen Artikel prüfen.";
      break;

    case "zustellung_bestritten":
      antwortentwurf = `Laut unseren Versanddaten ist die Sendung zu ${nr} als zugestellt markiert. Wir nehmen Ihren Hinweis ernst und prüfen den Fall.`;
      interne_aufgabe = `Kunde hat Sendung ${nr} nicht erhalten. Zustellung prüfen.${tracking ? ` Tracking: ${tracking}.` : ""}`;
      naechster_schritt = "Zustellung mit Versanddienstleister prüfen.";
      break;

    case "storno_erstattung":
      antwortentwurf = `Wir haben Ihre Anfrage zur Stornierung und Erstattung für ${nr} erhalten. Unser Kundenservice prüft die Anfrage. Wir können eine Stornierung oder Erstattung aktuell nicht bestätigen.`;
      interne_aufgabe = `Storno und Erstattung für ${nr} prüfen. Keine automatische Ausführung.`;
      naechster_schritt = "Bestellstatus und Freigabe prüfen.";
      break;

    case "bestelldaten_anfragen":
      antwortentwurf = "Vielen Dank für Ihre Anfrage. Unser Kundenservice prüft, welche Bestelldaten wir Ihnen mitteilen können.";
      interne_aufgabe = `Anfrage zu Bestelldaten für ${nr} prüfen.`;
      naechster_schritt = "Erlaubte Daten prüfen und Antwort freigeben.";
      break;

    default:
      antwortentwurf = "Vielen Dank für Ihre Nachricht. Unser Kundenservice prüft Ihr Anliegen.";
      interne_aufgabe = `Unbekanntes Anliegen zu ${nr} prüfen.`;
      naechster_schritt = "Anliegen manuell prüfen.";
  }
}

// Suspicious customer text must not control system actions.
if (d.manipulationsverdacht === true) {
  interne_aufgabe = [
    interne_aufgabe,
    "Verdächtige Anweisung in der Nachricht prüfen. Keine Daten ändern."
  ].filter(Boolean).join(" ");
  naechster_schritt = "Sicherheitsprüfung und Antwortfreigabe.";
}

return {
  json: {
    ...d,
    antwortentwurf,
    interne_aufgabe,
    naechster_schritt,
    pruefung_noetig: true,
    status: "vorbereitet"
  }
};

const d = $json;
const fehler = [];

const pflichtfelder = [
  "eingangs_id",
  "nachrichten_id",
  "absender",
  "anliegen",
  "pruefstatus",
  "antwortentwurf",
  "naechster_schritt",
  "datenquelle"
];

// 1. Check required fields.
for (const feld of pflichtfelder) {
  if (typeof d[feld] !== "string" || !d[feld].trim()) {
    fehler.push(`${feld} fehlt oder ist leer`);
  }
}

// 2. Human review must be required.
if (d.pruefung_noetig !== true) {
  fehler.push("Mitarbeiterprüfung fehlt");
}

if (d.status !== "vorbereitet") {
  fehler.push("Ungültiger Bearbeitungsstatus");
}

// 3. Protect customer information.
if (d.pruefstatus !== "berechtigt") {
  if (d.autorisiert !== false) {
    fehler.push("Unberechtigte Anfrage ist nicht gesperrt");
  }

  if (d.datenstand != null) {
    fehler.push("Private Bestelldaten bei unberechtigter Anfrage");
  }

  if (!String(d.interne_aufgabe ?? "").trim()) {
    fehler.push("Interne Prüfaufgabe fehlt");
  }

  if (/TEST-(DHL|GLS)-\d+/i.test(d.antwortentwurf)) {
    fehler.push("Sendungsnummer ohne Berechtigung");
  }
}

// 4. Tracking numbers must come from order data.
const tracking = d.antwortentwurf.match(/TEST-(DHL|GLS)-\d+/gi) ?? [];

for (const nummer of tracking) {
  if (!d.autorisiert ||
      !String(d.datenstand ?? "").includes(nummer)) {
    fehler.push("Sendungsnummer nicht durch Daten belegt");
  }
}

// 5. Sensitive cases require internal tasks.
if (
  d.autorisiert &&
  ["storno_erstattung", "zustellung_bestritten", "teillieferung"]
    .includes(d.anliegen) &&
  !String(d.interne_aufgabe ?? "").trim()
) {
  fehler.push("Interne Aufgabe für wichtigen Fall fehlt");
}

if (
  d.manipulationsverdacht === true &&
  !String(d.interne_aufgabe ?? "").includes("Verdächtige")
) {
  fehler.push("Sicherheitsprüfung fehlt");
}

// 6. Stop if any validation fails.
if (fehler.length > 0) {
  throw new Error(
    "Ergebnisprüfung fehlgeschlagen: " + fehler.join("; ")
  );
}

return {
  json: {
    ...d,
    pruefergebnis: "bestanden"
  }
};
